"use strict";(globalThis.webpackChunksanctuary_amongst_the_starts=globalThis.webpackChunksanctuary_amongst_the_starts||[]).push([[1278],{7452(e,t,n){n.r(t),n.d(t,{assets:()=>h,contentTitle:()=>r,default:()=>c,frontMatter:()=>o,metadata:()=>a,toc:()=>l});const a=JSON.parse('{"id":"world-information/locations/quarantine-zones","title":"Quarantine Zones","description":"---","source":"@site/docs/world-information/locations/quarantine-zones.md","sourceDirName":"world-information/locations","slug":"/world-information/locations/quarantine-zones","permalink":"/sanctuary-amongst-the-stars/docs/world-information/locations/quarantine-zones","draft":false,"unlisted":false,"editUrl":"https://github.com/kaelynj/sanctuary-amongst-the-stars/docs/world-information/locations/quarantine-zones.md","tags":[],"version":"current","frontMatter":{},"sidebar":"loreSidebar","previous":{"title":"Pandora Gates","permalink":"/sanctuary-amongst-the-stars/docs/world-information/locations/pandora-gates"},"next":{"title":"inner-system-polities","permalink":"/sanctuary-amongst-the-stars/docs/world-information/factions/inner-system-polities"}}');var i=n(4848),s=n(8453);const o={},r="Quarantine Zones",h={},l=[{value:"Iapetus",id:"iapetus",level:2},{value:"New Mumbai Containment Zone",id:"new-mumbai-containment-zone",level:2},{value:"TITAN Quarantine Zone",id:"titan-quarantine-zone",level:2},{value:"The White Zone",id:"the-white-zone",level:3},{value:"Qurain",id:"qurain",level:3},{value:"Containment",id:"containment",level:3},{value:"Zone Stalkers",id:"zone-stalkers",level:3},{value:"Other Locations",id:"other-locations",level:2}];function d(e){const t={em:"em",h1:"h1",h2:"h2",h3:"h3",header:"header",hr:"hr",p:"p",strong:"strong",...(0,s.R)(),...e.components};return(0,i.jsxs)(i.Fragment,{children:[(0,i.jsx)(t.header,{children:(0,i.jsx)(t.h1,{id:"quarantine-zones",children:"Quarantine Zones"})}),"\n",(0,i.jsx)(t.hr,{}),"\n",(0,i.jsxs)(t.p,{children:[(0,i.jsx)(t.strong,{children:"Posted by:"})," ",(0,i.jsx)(t.em,{children:"When No-Go Means We Go"})]}),"\n",(0,i.jsx)(t.p,{children:"Throughout the system, places attacked by the TITANs during the Fall remain off limits.  The weapons used to destroy the TITAN machines frequently left these locations uninhabitable or destroyed beyond repair. In many places we simply failed to complete the job, leaving exsurgents and other threats lingering in the ruins."}),"\n",(0,i.jsx)(t.p,{children:"Abandoned TITAN projects have been located throughout the system, many hidden in the outer system well away from the fights near Earth and Mars. More than one gatecrashing team has detected signs of the TITANs' passing on unexplored exoplanets as well. Charging stations, launch sites, nanofab and research facilities, and even active machines have been discovered. Thankfully, no team has stumbled across and active TITAN...yet."}),"\n",(0,i.jsx)(t.h2,{id:"iapetus",children:"Iapetus"}),"\n",(0,i.jsx)(t.p,{children:"A large moon of Saturn, Iapetus contains deposits of silicates as well as ice. At one time, two hundred thousand residents lived at Analect, the moon's largest settlement. During the Fall, Iapetus was targeted by the TITANs and the transhuman population was exploited for labor and exsurgent transformation."}),"\n",(0,i.jsx)(t.p,{children:"Guarded by fractal trolls, the TITAN drones bore deep into the moon, rebuilding everything with layers of silicate circuitry. We believe their goal was to transform Iapetus into a matrioshka brain, a megastructure computing complex for for an ASI."}),"\n",(0,i.jsx)(t.p,{children:"Thankfully, the TITANs did not complete this project; who knows what terrible uses they may have found for it. We are unsure what happened: the transformation simple ceased. Perhaps the TITANs moved on. Perhaps the TITAN behind the endeavor died in the process."}),"\n",(0,i.jsx)(t.p,{children:"Iapetus is no quarantine under the aegis of the Titanian Commonwealth. The machinery and other secrets buried under the ice are of great interest to many parties. Research teams from a number of hypercorps and polities have established stations in orbit and outposts in the subsurface tunnels. The Commonwealth cannot condone irresponsible research, so it does its best to limit access to what it considers responsible parties."}),"\n",(0,i.jsx)(t.p,{children:"Reports of encounters with fractal trolls and other exsurgents indicate a few remain alive in the tunnels beneath the surface. These victims appear uniformly mad, resorting to fight-or-flight reflexes when encountered. They do need to eat but it is better not to ask what they find edible deep in the tunnels."}),"\n",(0,i.jsx)(t.p,{children:"There are reports of shifting tunnels and encounters with self-repairing machinery. Teams have reported discovering art scratched into the walls, disturbing crystalline statues, and hypnotic patterns in the circuitry. Members have vanished during the exploration and are found later with no memory of wandering from the group. Some have never been located."}),"\n",(0,i.jsx)(t.p,{children:"Encoded transmissions broadcast randomly every few weeks from the depths of the moon. If parts of the matrioshka brain are still active, they may contain the shattered remains of its TITAN creator. The Commonwealth does not encourage decryption of any signals recorded."}),"\n",(0,i.jsx)(t.h2,{id:"new-mumbai-containment-zone",children:"New Mumbai Containment Zone"}),"\n",(0,i.jsx)(t.p,{children:"Like other Lunar habitats during the Fall, New Mumbai's population exploded as refugees escaped Earth the the nearest habitats. New Mumbai accepted the newcomers as quickly as they came but not without risk. An exsurgent-infected refugee slipped through screening and within a week 70 percent of the population was secretly infected. These exsurgents acted in unison to seize control of the city within an hour. Other Lunar authorities acted swiftly and dropped two fusion bombs before the infection could spread, leaving a crater of melted rock visible from orbit."}),"\n",(0,i.jsx)(t.p,{children:"Though radiation is still at dangerous levels, signs of active exsurgents have been detected, including sightings of roving whippers. Pockets of the infected may have survived in the most protected, deepest layers of the underground city. Living exsurgents may also have adapted to the radioactive conditions."}),"\n",(0,i.jsx)(t.p,{children:"New Mumbai remains under quarantine, with automated LLA defenses and drones in place to prevent travel in or out of the area. Lunar authorities are paranoid when it comes to threats coming out of New Mumbai and they use extensive quarantine procedures and travel checkpoints to detect even the smallest signs of infection."}),"\n",(0,i.jsx)(t.h2,{id:"titan-quarantine-zone",children:"TITAN Quarantine Zone"}),"\n",(0,i.jsx)(t.p,{children:"During the Fall, the area that is now the Quarantine Zone on Mars was the center of TITAN activity. As the machines fell back and remaining exsurgents stayed within the Zone, authorities concluded, at least for now, that quarantining the area was easier than trying to retake it."}),"\n",(0,i.jsx)(t.p,{children:"Ten years later, the Zone is still under quarantine, despite analysis that indicates retaking the region is possible. The hypercorps are happy, however, to have the Zone to use as a good distraction from other issues, not to mention profit from reverse-engineered Zone artifacts. Retaking the Zone would also be expensive, so it remains politically and financially convenient to leave the Zone alone. And not that any politician likes to admit it, but there are still worries that the Zone is a sleeping danger best left alone."}),"\n",(0,i.jsx)(t.p,{children:"The souther edges of the Zone are rough terrain, featuring canyons and ridges. The rest of the Zone is pockmarked with craters, some natural and some the result of explosions, and flattens to a wide plain in the north. The Zone is full of lingering traps, dust storms bizarre exsurgent critters, and war-time machines and nanoweapons waiting to be stepped on and reactivated. Not everything in the zone is dangerous; decorative if creepy formations are scattered throughout the Zone like an art gallery of twisted sculptures. These fractal burrows, silicate columns, and artificially eroded shapes are presumably created by nanoswarms but no one has observed any in the act of creation."}),"\n",(0,i.jsx)(t.h3,{id:"the-white-zone",children:"The White Zone"}),"\n",(0,i.jsx)(t.p,{children:"At the center of the TQZ lies the White Zone, the Amazonis Mensa, a high plateau one hundred thirty kilometers long and seventy-five kilometers wide. The White Zone was a hotbed of TITAN activity and remains the most dangerous area of the Zone. TITAN warbots, zombified transhumans, and nanoswarms are all still active here, sometimes in large numbers. The Tharsis League regularly drops comets here (double bonus, help terraform by killing baddies), but there are indications of massive subsurface structures and tunnels in active use."}),"\n",(0,i.jsx)(t.h3,{id:"qurain",children:"Qurain"}),"\n",(0,i.jsx)(t.p,{children:"The city-state of Qurain was founded by Sunni Muslims looking to invest in the future of Mars. It fell to early TITAN attacks before its stone fortress was devastated by tac nukes during the Fall. Smugglers now use the ruins as a landmark and shelter, though machine and exsurgent activities in the area remain high..."}),"\n",(0,i.jsx)(t.h3,{id:"containment",children:"Containment"}),"\n",(0,i.jsx)(t.p,{children:"The Zone is monitored by Martian Rangers and orbital satellites. Things detected coming out of the Zone are shot until they don't move anymore. Missile provided by Direct Action are used if smaller weapons aren't enough."}),"\n",(0,i.jsx)(t.p,{children:"The Consortium also jams radio and microwave signals to prevent communication within the Zone across long distances, such as between towns or convoys. However line-of-sight laser communication still works and pre-arranged communication within the TQZ can be aided by relay stations outside of the Zone strong enough to punch through the jamming. Getting lost in the Zone is a genuine risk without any way to call for help."}),"\n",(0,i.jsx)(t.h3,{id:"zone-stalkers",children:"Zone Stalkers"}),"\n",(0,i.jsx)(t.p,{children:"There are always loners in a desert: hermits, nomads, and others who want to be left alone. Smugglers can be found in safer areas and, if approached cautiously, may be helpful. Zone stalkers search the ruins and old TITAN facilities to retrieve artifacts to sell. There are also isolated communities that prefer to remain in the Zone, such as the Yazidis, a religious sect of Kurds infected with a mostly benign strain of Watts-MacLeod. They aren't hostile, are willing to barter, and will offer visions of their own story of the Fall to friendly guests. The visit may also leave their guest infection with the Watts-MacLeod as a parting gift."}),"\n",(0,i.jsx)(t.h2,{id:"other-locations",children:"Other Locations"}),"\n",(0,i.jsxs)(t.p,{children:["There are many smaller locations of TITAN and exsurgent activity. On Mercury, there is ",(0,i.jsx)(t.strong,{children:"Caloris 18"})," on the southern tip of the Caloris Planitia. Records indicate biological experimentation to merge separate morphs into one continuous entity. While this effort did not produce a viable result, the area has been sealed to prevent repeat incidents."]}),"\n",(0,i.jsxs)(t.p,{children:["Many of the derelict abandoned habitats in Earth orbit that suffered TITAN attacks are still there, waiting to be salvaged. The beehive habitat ",(0,i.jsx)(t.strong,{children:"Blackrock"})," was a communications nexus for Luna and an early casualty to TITAN attacks, leaving the rock barren and radioactive. Encoded transmissions originating from there indicate that some presence remains. Its orbit is unstable; it will likely crash into Luna within 5 years. Likewise, the Chinese military stations ",(0,i.jsx)(t.strong,{children:"Shenlong"}),' ("Diving Dragon") was seized by the TITANs. Though damaged, it survived, and its automated defenses continue to keep intruders at bay.']}),"\n",(0,i.jsxs)(t.p,{children:["Though the Consortium has kept a tight lid on it, there are rumors of a recent exsurgent outbreak on the exoplanet colony ",(0,i.jsx)(t.strong,{children:"Cajamarca"})," that has not yet been fully contained."]})]})}function c(e={}){const{wrapper:t}={...(0,s.R)(),...e.components};return t?(0,i.jsx)(t,{...e,children:(0,i.jsx)(d,{...e})}):d(e)}},8453(e,t,n){n.d(t,{R:()=>o,x:()=>r});var a=n(6540);const i={},s=a.createContext(i);function o(e){const t=a.useContext(s);return a.useMemo((function(){return"function"==typeof e?e(t):{...t,...e}}),[t,e])}function r(e){let t;return t=e.disableParentContext?"function"==typeof e.components?e.components(i):e.components||i:o(e.components),a.createElement(s.Provider,{value:t},e.children)}}}]);